    for nm,D in [("Q",Qv),("K",Kv),("V",Vv)]:
        print(f"   {nm} dirs: in T {[round(proj(D[:,i],T),2) for i in range(D.shape[1])]}  in P {[round(proj(D[:,i],P),2) for i in range(D.shape[1])]}")
